import React, { useState } from 'react';
import { Data } from './data';
import './internships.css';
import { SectionHeading } from '../section-heading';

export function Internships() {
  const [expandedCard, setExpandedCard] = useState(null);

  return (
    <section className="internships section" id="internships">
      <div className="container">
        <SectionHeading eyebrow="Where I’ve contributed" title="Experience" subtitle="A few places where I’ve learned, collaborated, and made an impact." />
        <div className="internships__container grid">
          {Data.map((item) => {
            const isExpanded = expandedCard === item.title;
            return (
              <article className="internships__card" key={item.title}>
                <div className="internships__content">
                  <span className="internship__icon" aria-hidden="true"><i className="uil uil-briefcase-alt"></i></span>
                  <h3 className="internship__title">{item.title}</h3>
                  <p className="internship__description">{item.description}</p>
                  <span className="internship__role">{item.role}</span>
                  {isExpanded && <p className="internship__details">{item.details}</p>}
                  <button type="button" className="internships__details-button" aria-expanded={isExpanded} onClick={() => setExpandedCard(isExpanded ? null : item.title)}>
                    {isExpanded ? 'Show less' : 'View details'} <i className={`uil ${isExpanded ? 'uil-arrow-up' : 'uil-arrow-right'}`} aria-hidden="true"></i>
                  </button>
                </div>
              </article>
            );
          })}
        </div>
      </div>
    </section>
  );
}
